static ssize_t recv_some(int fd, void *buf, size_t len)
{
    for (;;) {
        ssize_t n = recv(fd, buf, len, 0);
        if (n >= 0 || errno != EINTR)
            return n;
    }
}

/* Locate "\r\n\r\n" in buf[0..len), scanning from `from`. Returns the offset
 * just past the terminator, or 0 if not present. */
static size_t find_header_end(const char *buf, size_t len, size_t from)
{
    for (size_t i = from; i + 4 <= len; i++) {
        if (buf[i] == '\r' && buf[i + 1] == '\n' && buf[i + 2] == '\r' && buf[i + 3] == '\n')
            return i + 4;
    }
    return 0;
}

static bool is_tchar(unsigned char c)
{
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9'))
        return true;
    return c != '\0' && strchr("!#$%&'*+-.^_`|~", c) != NULL;
}

static char *trim_ows(char *s, char *end)
{
    while (s < end && (*s == ' ' || *s == '\t'))
        s++;
    while (end > s && (end[-1] == ' ' || end[-1] == '\t'))
        end--;
    *end = '\0';
    return s;
}

/* Strict decimal parse; rejects signs, spaces and overflow. */
static bool parse_content_length(const char *s, size_t *out)
{
    if (*s == '\0')
        return false;
    size_t v = 0;
    for (; *s; s++) {
        if (*s < '0' || *s > '9')
            return false;
        if (__builtin_mul_overflow(v, 10, &v) ||
            __builtin_add_overflow(v, (size_t)(*s - '0'), &v))
            return false;
    }
    *out = v;
    return true;
}

/* Parse the request line and headers in place (buf is NUL-terminated at the
 * end of the header block). Returns 0 or an HTTP error status. */
static int parse_head(char *buf, http_request *req, bool *has_length)
{
    char *line_end = strstr(buf, "\r\n");
    if (!line_end)
        return 400;
    *line_end = '\0';

    /* request-line = method SP request-target SP HTTP-version */
    char *sp1 = strchr(buf, ' ');
    if (!sp1 || sp1 == buf)
        return 400;
    *sp1 = '\0';
    for (const char *p = buf; *p; p++)
        if (!is_tchar((unsigned char)*p))
            return 400;
    char *target = sp1 + 1;
    char *sp2 = strchr(target, ' ');
    if (!sp2 || sp2 == target)
        return 400;
    *sp2 = '\0';
    const char *version = sp2 + 1;
    if (strncmp(version, "HTTP/1.", 7) != 0 || version[7] < '0' || version[7] > '9' ||
        version[8] != '\0')
        return strncmp(version, "HTTP/", 5) == 0 ? 505 : 400;
    if (target[0] != '/')
        return 400;

    /* Paths in this API never carry queries, but ignore one defensively. */
    char *query = strchr(target, '?');
    if (query)
        *query = '\0';
    req->method = buf;
    req->path = target;
    req->path_len = strlen(target);

    *has_length = false;
    char *line = line_end + 2;
    while (*line != '\0') {
        char *eol = strstr(line, "\r\n");
        if (!eol)
            return 400;
        if (eol == line)
            break; /* blank line terminating the header block */
        char *colon = memchr(line, ':', (size_t)(eol - line));
        if (!colon || colon == line)
            return 400;
        for (const char *p = line; p < colon; p++)
            if (!is_tchar((unsigned char)*p))
                return 400;
        *colon = '\0';
        char *value = trim_ows(colon + 1, eol);

        if (strcasecmp(line, "Content-Length") == 0) {
            size_t len;
            if (!parse_content_length(value, &len))
                return 400;
            if (*has_length && len != req->content_length)
                return 400;
            req->content_length = len;
            *has_length = true;
        } else if (strcasecmp(line, "Transfer-Encoding") == 0) {
            return 501; /* chunked uploads are not supported */
        }
        line = eol + 2;
    }
    return 0;
}

int http_read_request(int fd, http_request *req)
{
    *req = (http_request){0};

    char *buf = malloc(HTTP_MAX_HEADER + 1);
    if (!buf)
        return 500;
    req->header_buf_ = buf;

    size_t len = 0, head_end = 0;
    while (head_end == 0) {
        if (len == HTTP_MAX_HEADER)
            return 431;
        ssize_t n = recv_some(fd, buf + len, HTTP_MAX_HEADER - len);
        if (n <= 0)
            return len == 0 ? -1 : (n == 0 ? 400 : -1);
        size_t from = len >= 3 ? len - 3 : 0;
        len += (size_t)n;
        head_end = find_header_end(buf, len, from);
    }

    /* Keep the body prefix aside before NUL-terminating the head. */
    size_t prefix_len = len - head_end;
    char saved = buf[head_end];
    buf[head_end] = '\0';

    bool has_length;
    int status = parse_head(buf, req, &has_length);
    if (status != 0)
        return status;
    if (!has_length || req->content_length == 0)
        return 0;
    if (req->content_length > HTTP_MAX_BODY) {
        req->body_too_large = true;
        return 0;
    }

    uint8_t *body = malloc(req->content_length);
    if (!body)
        return 500;
    req->body = body;

    buf[head_end] = saved;
    size_t have = prefix_len < req->content_length ? prefix_len : req->content_length;
    memcpy(body, buf + head_end, have);
    while (have < req->content_length) {
        ssize_t n = recv_some(fd, body + have, req->content_length - have);
        if (n <= 0)
            return n == 0 ? 400 : -1;
        have += (size_t)n;
    }
    req->body_len = have;
    return 0;
}

void http_request_free(http_request *req)
{
    free(req->body);
    free(req->header_buf_);
    *req = (http_request){0};
}

static const char *reason_phrase(int status)
{
    switch (status) {
    case 200: return "OK";
    case 201: return "Created";
    case 204: return "No Content";
    case 400: return "Bad Request";
    case 404: return "Not Found";
    case 405: return "Method Not Allowed";
    case 413: return "Content Too Large";
    case 431: return "Request Header Fields Too Large";
    case 500: return "Internal Server Error";
    case 501: return "Not Implemented";
    case 505: return "HTTP Version Not Supported";
    default:  return "Unknown";
    }
}

int http_send_response(int fd, int status, const char *extra_headers,
                       const void *body, size_t body_len)
{
    char head[512];
    int w = snprintf(head, sizeof head,
                     "HTTP/1.1 %d %s\r\n"
                     "Content-Length: %zu\r\n"
                     "Connection: close\r\n"
                     "%s"
                     "\r\n",
                     status, reason_phrase(status), body_len,
                     extra_headers ? extra_headers : "");
    if (w < 0 || (size_t)w >= sizeof head)
        return -1;

    struct iovec iov[2] = {
        {.iov_base = head, .iov_len = (size_t)w},
        {.iov_base = (void *)(uintptr_t)body, .iov_len = body ? body_len : 0},
    };
    int iovcnt = iov[1].iov_len ? 2 : 1;
    struct iovec *cur = iov;

    while (iovcnt > 0) {
        ssize_t n = writev(fd, cur, iovcnt);
        if (n < 0) {
            if (errno == EINTR)
                continue;
            return -1;
        }
        size_t done = (size_t)n;
        while (iovcnt > 0 && done >= cur->iov_len) {
            done -= cur->iov_len;
            cur++;
            iovcnt--;
        }
        if (iovcnt > 0) {
            cur->iov_base = (char *)cur->iov_base + done;
            cur->iov_len -= done;
        }
    }
    return 0;
}

static int64_t now_ms(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}

void http_close_gracefully(int fd)
{
    enum { LINGER_MS = 2000, LINGER_MAX_BYTES = 8 * 1024 * 1024 };

    if (shutdown(fd, SHUT_WR) == 0) {
        char sink[16384];
        size_t total = 0;
        int64_t deadline = now_ms() + LINGER_MS;
        while (total < LINGER_MAX_BYTES) {
            int64_t left = deadline - now_ms();
            if (left <= 0)
                break;
            struct pollfd pfd = {.fd = fd, .events = POLLIN};
            int r = poll(&pfd, 1, (int)left);
            if (r < 0 && errno == EINTR)
                continue;
            if (r <= 0)
                break;
            ssize_t n = recv_some(fd, sink, sizeof sink);
            if (n <= 0)
                break;
            total += (size_t)n;
        }
    }
    close(fd);
}

#ifndef KVHTTP_HTTP_H
#define KVHTTP_HTTP_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* Minimal HTTP/1.1 request reading and response writing for one request per
 * connection (the server always answers with Connection: close). */

enum {
    HTTP_MAX_HEADER = 16 * 1024,
    HTTP_MAX_BODY = 1024 * 1024,
};

typedef struct {
    const char *method; /* NUL-terminated, points into the header buffer */
    const char *path;   /* NUL-terminated, points into the header buffer */
    size_t path_len;
    uint8_t *body;      /* malloc'd, NULL when there is no body */
    size_t body_len;
    size_t content_length;
    bool body_too_large; /* Content-Length exceeded HTTP_MAX_BODY; body not read */
    char *header_buf_;   /* owned storage for method/path */
} http_request;

/* Result of http_read_request(): 0 on success, otherwise the HTTP status the
 * server should answer with (400, 431, 501, ...), or -1 when the connection
 * failed and no response can be sent. */
int http_read_request(int fd, http_request *req);
void http_request_free(http_request *req);

/* Send a full response. `extra_headers` (may be NULL) is a block of
 * "Name: value\r\n" lines. Returns 0 or -1 on I/O error. */
int http_send_response(int fd, int status, const char *extra_headers,
                       const void *body, size_t body_len);

/* Half-close and discard any unread input so the peer reliably receives the
 * response instead of a connection reset, then close the socket. */
void http_close_gracefully(int fd);

#endif /* KVHTTP_HTTP_H */

#include "kvstore.h"

#include <errno.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

struct entry {
    struct entry *next;
    uint64_t hash;
    uint8_t *val;
    size_t vlen;
    size_t klen;
    char key[]; /* klen bytes + NUL */
};

struct kv_store {
    pthread_rwlock_t lock;
    struct entry **buckets;
    size_t nbuckets; /* power of two */
    size_t count;
};

enum { INITIAL_BUCKETS = 64 };

static uint64_t hash_key(const char *key, size_t len)
{
    /* FNV-1a, 64-bit */
    uint64_t h = 0xcbf29ce484222325u;
    for (size_t i = 0; i < len; i++) {
        h ^= (unsigned char)key[i];
        h *= 0x100000001b3u;
    }
    return h;
}

kv_store *kv_create(void)
{
    kv_store *s = calloc(1, sizeof *s);
    if (!s)
        return NULL;
    s->buckets = calloc(INITIAL_BUCKETS, sizeof *s->buckets);
    if (!s->buckets || pthread_rwlock_init(&s->lock, NULL) != 0) {
        free(s->buckets);
        free(s);
        return NULL;
    }
    s->nbuckets = INITIAL_BUCKETS;
    return s;
}

void kv_destroy(kv_store *s)
{
    if (!s)
        return;
    for (size_t i = 0; i < s->nbuckets; i++) {
        struct entry *e = s->buckets[i];
        while (e) {
            struct entry *next = e->next;
            free(e->val);
            free(e);
            e = next;
        }
    }
    free(s->buckets);
    pthread_rwlock_destroy(&s->lock);
    free(s);
}

/* Returns the link pointing at the matching entry, or at the chain's NULL tail. */
static struct entry **find_slot(const kv_store *s, const char *key, size_t klen, uint64_t h)
{
    struct entry **pp = &s->buckets[h & (s->nbuckets - 1)];
    while (*pp) {
        const struct entry *e = *pp;
        if (e->hash == h && e->klen == klen && memcmp(e->key, key, klen) == 0)
            break;
        pp = &(*pp)->next;
    }
    return pp;
}

/* Double the table. Failure is harmless: chains just get longer. */
static void maybe_grow(kv_store *s)
{
    if (s->count < s->nbuckets || s->nbuckets > SIZE_MAX / 2 / sizeof *s->buckets)
        return;
    size_t ncap = s->nbuckets * 2;
    struct entry **nb = calloc(ncap, sizeof *nb);
    if (!nb)
        return;
    for (size_t i = 0; i < s->nbuckets; i++) {
        struct entry *e = s->buckets[i];
        while (e) {
            struct entry *next = e->next;
            struct entry **head = &nb[e->hash & (ncap - 1)];
            e->next = *head;
            *head = e;
            e = next;
        }
    }
    free(s->buckets);
    s->buckets = nb;
    s->nbuckets = ncap;
}

int kv_put(kv_store *s, const char *key, size_t klen, uint8_t *val, size_t vlen,
           bool *created)
{
    uint64_t h = hash_key(key, klen);

    /* Allocate the potential new entry outside the lock. */
    struct entry *fresh = malloc(sizeof *fresh + klen + 1);
    if (!fresh)
        return ENOMEM;
    fresh->next = NULL;
    fresh->hash = h;
    fresh->val = val;
    fresh->vlen = vlen;
    fresh->klen = klen;
    memcpy(fresh->key, key, klen);
    fresh->key[klen] = '\0';

    uint8_t *old_val = NULL;
    pthread_rwlock_wrlock(&s->lock);
    struct entry **slot = find_slot(s, key, klen, h);
    if (*slot) {
        old_val = (*slot)->val;
        (*slot)->val = val;
        (*slot)->vlen = vlen;
        *created = false;
    } else {
        *slot = fresh;
        fresh = NULL;
        s->count++;
        maybe_grow(s);
        *created = true;
    }
    pthread_rwlock_unlock(&s->lock);

    free(old_val);
    free(fresh);
    return 0;
}

int kv_get(kv_store *s, const char *key, size_t klen, uint8_t **out, size_t *outlen)
{
    uint64_t h = hash_key(key, klen);
    int rc = 0;

    pthread_rwlock_rdlock(&s->lock);
    const struct entry *e = *find_slot(s, key, klen, h);
    if (!e) {
        rc = ENOENT;
    } else {
        uint8_t *copy = malloc(e->vlen ? e->vlen : 1);
        if (!copy) {
            rc = ENOMEM;
        } else {
            if (e->vlen)
                memcpy(copy, e->val, e->vlen);
            *out = copy;
            *outlen = e->vlen;
        }
    }
    pthread_rwlock_unlock(&s->lock);
    return rc;
}

bool kv_delete(kv_store *s, const char *key, size_t klen)
{
    uint64_t h = hash_key(key, klen);
    struct entry *victim = NULL;

    pthread_rwlock_wrlock(&s->lock);
    struct entry **slot = find_slot(s, key, klen, h);
    if (*slot) {
        victim = *slot;
        *slot = victim->next;
        s->count--;
    }
    pthread_rwlock_unlock(&s->lock);

    if (!victim)
        return false;
    free(victim->val);
    free(victim);
    return true;
}

static int cmp_key(const void *a, const void *b)
{
    const kv_key *x = a, *y = b;
    size_t n = x->len < y->len ? x->len : y->len;
    int c = memcmp(x->data, y->data, n);
    if (c != 0)
        return c;
    return (x->len > y->len) - (x->len < y->len);
}

void kv_keys_free(kv_key *keys, size_t count)
{
    if (!keys)
        return;
    for (size_t i = 0; i < count; i++)
        free(keys[i].data);
    free(keys);
}

int kv_keys(kv_store *s, kv_key **out, size_t *count)
{
    int rc = 0;
    size_t n = 0;
    kv_key *keys = NULL;

    pthread_rwlock_rdlock(&s->lock);
    if (s->count > 0) {
        keys = calloc(s->count, sizeof *keys);
        if (!keys) {
            rc = ENOMEM;
            goto unlock;
        }
        for (size_t i = 0; i < s->nbuckets; i++) {
            for (const struct entry *e = s->buckets[i]; e; e = e->next) {
                char *k = malloc(e->klen + 1);
                if (!k) {
                    rc = ENOMEM;
                    goto unlock;
                }
                memcpy(k, e->key, e->klen + 1);
                keys[n].data = k;
                keys[n].len = e->klen;
                n++;
            }
        }
    }
unlock:
    pthread_rwlock_unlock(&s->lock);

    if (rc != 0) {
        kv_keys_free(keys, n);
        return rc;
    }
    if (n > 1)
        qsort(keys, n, sizeof *keys, cmp_key);
    *out = keys;
    *count = n;
    return 0;
}

#ifndef KVHTTP_KVSTORE_H
#define KVHTTP_KVSTORE_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* Thread-safe in-memory key/value store. Keys are arbitrary byte strings of
 * known length (validation is the caller's job); values are opaque bytes. */
typedef struct kv_store kv_store;

/* A key returned by kv_keys(); NUL-terminated for convenience. */
typedef struct {
    size_t len;
    char *data;
} kv_key;

kv_store *kv_create(void);
void kv_destroy(kv_store *s);

/* Store `val` under `key`, taking ownership of `val` (allocated with malloc)
 * on success. *created reports whether the key was new.
 * Returns 0 or ENOMEM (in which case the caller still owns `val`). */
int kv_put(kv_store *s, const char *key, size_t klen, uint8_t *val, size_t vlen,
           bool *created);

/* Copy the value for `key` into a fresh malloc'd buffer.
 * Returns 0, ENOENT, or ENOMEM. */
int kv_get(kv_store *s, const char *key, size_t klen, uint8_t **out, size_t *outlen);

/* Returns true if the key existed and was removed. */
bool kv_delete(kv_store *s, const char *key, size_t klen);

/* Snapshot all keys, sorted ascending by byte value. Free with kv_keys_free().
 * Returns 0 or ENOMEM. */
int kv_keys(kv_store *s, kv_key **out, size_t *count);
void kv_keys_free(kv_key *keys, size_t count);

#endif /* KVHTTP_KVSTORE_H */

#define _DARWIN_C_SOURCE
#define _POSIX_C_SOURCE 200809L

#include <arpa/inet.h>
#include <errno.h>
#include <netinet/in.h>
#include <netinet/tcp.h>
#include <pthread.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <unistd.h>

#include "http.h"
#include "kvstore.h"

enum { KEY_MAX_LEN = 64, IO_TIMEOUT_SEC = 15 };

static kv_store *g_store;

static bool valid_key(const char *k, size_t len)
{
    if (len == 0 || len > KEY_MAX_LEN)
        return false;
    for (size_t i = 0; i < len; i++) {
        unsigned char c = (unsigned char)k[i];
        bool ok = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
                  (c >= '0' && c <= '9') || c == '_' || c == '-';
        if (!ok)
            return false;
    }
    return true;
}

static int send_status(int fd, int status)
{
    return http_send_response(fd, status, NULL, NULL, 0);
}

static int send_405(int fd, const char *allow)
{
    char hdr[64];
    snprintf(hdr, sizeof hdr, "Allow: %s\r\n", allow);
    return http_send_response(fd, 405, hdr, NULL, 0);
}

static void handle_list(int fd)
{
    kv_key *keys = NULL;
    size_t n = 0;
    if (kv_keys(g_store, &keys, &n) != 0) {
        send_status(fd, 500);
        return;
    }

    /* Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is needed. */
    size_t cap = 2;
    for (size_t i = 0; i < n; i++)
        cap += keys[i].len + 3; /* quotes + comma */
    char *json = malloc(cap);
    if (!json) {
        kv_keys_free(keys, n);
        send_status(fd, 500);
        return;
    }
    size_t len = 0;
    json[len++] = '[';
    for (size_t i = 0; i < n; i++) {
        if (i > 0)
            json[len++] = ',';
        json[len++] = '"';
        memcpy(json + len, keys[i].data, keys[i].len);
        len += keys[i].len;
        json[len++] = '"';
    }
    json[len++] = ']';
    kv_keys_free(keys, n);

    http_send_response(fd, 200, "Content-Type: application/json\r\n", json, len);
    free(json);
}

static void handle_key(int fd, http_request *req, const char *key, size_t klen)
{
    const char *m = req->method;

    if (strcmp(m, "GET") == 0) {
        uint8_t *val = NULL;
        size_t vlen = 0;
        int rc = kv_get(g_store, key, klen, &val, &vlen);
        if (rc == ENOENT) {
            send_status(fd, 404);
        } else if (rc != 0) {
            send_status(fd, 500);
        } else {
            http_send_response(fd, 200, "Content-Type: application/octet-stream\r\n", val, vlen);
            free(val);
        }
    } else if (strcmp(m, "PUT") == 0) {
        if (req->body_too_large) {
            send_status(fd, 413);
            return;
        }
        uint8_t *val = req->body ? req->body : malloc(1);
        if (!val) {
            send_status(fd, 500);
            return;
        }
        bool created = false;
        if (kv_put(g_store, key, klen, val, req->body_len, &created) != 0) {
            if (val != req->body)
                free(val);
            send_status(fd, 500);
            return;
        }
        req->body = NULL; /* ownership moved into the store */
        send_status(fd, created ? 201 : 200);
    } else if (strcmp(m, "DELETE") == 0) {
        send_status(fd, kv_delete(g_store, key, klen) ? 204 : 404);
    } else {
        send_405(fd, "GET, PUT, DELETE");
    }
}

static void route(int fd, http_request *req)
{
    static const char kv_prefix[] = "/kv/";
    const size_t kv_prefix_len = sizeof kv_prefix - 1;
    const char *path = req->path;
    bool is_get = strcmp(req->method, "GET") == 0;

    if (strcmp(path, "/health") == 0) {
        if (is_get)
            http_send_response(fd, 200, "Content-Type: text/plain\r\n", "ok", 2);
        else
            send_405(fd, "GET");
    } else if (strcmp(path, "/kv") == 0) {
        if (is_get)
            handle_list(fd);
        else
            send_405(fd, "GET");
    } else if (strncmp(path, kv_prefix, kv_prefix_len) == 0) {
        const char *key = path + kv_prefix_len;
        size_t klen = req->path_len - kv_prefix_len;
        if (!valid_key(key, klen))
            send_status(fd, 400);
        else
            handle_key(fd, req, key, klen);
    } else {
        send_status(fd, 404);
    }
}

static void *connection_main(void *arg)
{
    int fd = (int)(intptr_t)arg;

    http_request req;
    int status = http_read_request(fd, &req);
    if (status == 0)
        route(fd, &req);
    else if (status > 0)
        send_status(fd, status);
    http_request_free(&req);

    http_close_gracefully(fd);
    return NULL;
}

static void configure_client(int fd)
{
    struct timeval tv = {.tv_sec = IO_TIMEOUT_SEC};
    int one = 1;
    (void)setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof tv);
    (void)setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof tv);
    (void)setsockopt(fd, IPPROTO_TCP, TCP_NODELAY, &one, sizeof one);
#ifdef SO_NOSIGPIPE
    (void)setsockopt(fd, SOL_SOCKET, SO_NOSIGPIPE, &one, sizeof one);
#endif
}

static int listen_on(uint16_t port)
{
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket");
        return -1;
    }
    int one = 1;
    (void)setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);

    struct sockaddr_in addr = {
        .sin_family = AF_INET,
        .sin_port = htons(port),
        .sin_addr.s_addr = htonl(INADDR_LOOPBACK),
    };
    if (bind(fd, (struct sockaddr *)&addr, sizeof addr) != 0) {
        perror("bind");
        close(fd);
        return -1;
    }
    if (listen(fd, SOMAXCONN) != 0) {
        perror("listen");
        close(fd);
        return -1;
    }
    return fd;
}

static bool parse_port(const char *s, uint16_t *out)
{
    char *end;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (end == s || *end != '\0' || errno == ERANGE || v < 1 || v > 65535)
        return false;
    *out = (uint16_t)v;
    return true;
}

int main(int argc, char **argv)
{
    uint16_t port;
    if (argc != 2 || !parse_port(argv[1], &port)) {
        fprintf(stderr, "usage: %s <port>\n", argc > 0 ? argv[0] : "app");
        return EXIT_FAILURE;
    }

    signal(SIGPIPE, SIG_IGN);

    g_store = kv_create();
    if (!g_store) {
        fprintf(stderr, "out of memory\n");
        return EXIT_FAILURE;
    }

    int lfd = listen_on(port);
    if (lfd < 0)
        return EXIT_FAILURE;

    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);

    for (;;) {
        int cfd = accept(lfd, NULL, NULL);
        if (cfd < 0) {
            if (errno == EINTR || errno == ECONNABORTED)
                continue;
            if (errno == EMFILE || errno == ENFILE || errno == ENOBUFS || errno == ENOMEM) {
                usleep(10000); /* resource pressure: back off and retry */
                continue;
            }
            perror("accept");
            break;
        }
        configure_client(cfd);

        pthread_t tid;
        int rc = pthread_create(&tid, &attr, connection_main, (void *)(intptr_t)cfd);
        if (rc != 0) {
            send_status(cfd, 500);
            close(cfd);
        }
    }

    pthread_attr_destroy(&attr);
    close(lfd);
    kv_destroy(g_store);
    return EXIT_FAILURE;
}
